class Solution {
public:
    int maxDiff(int num) {
        string s = to_string(num), hi = s, lo = s;
        char a = '9';
        for (char c : s) if (c != '9') { a = c; break; }
        for (char& c : hi) if (c == a) c = '9';
        if (s[0] != '1') {
            char old = s[0];
            for (char& c : lo) if (c == old) c = '1';
        } else {
            char old = 0;
            for (int i = 1; i < (int)s.size(); ++i)
                if (s[i] != '0' && s[i] != '1') { old = s[i]; break; }
            if (old) for (char& c : lo) if (c == old) c = '0';
        }
        return stoi(hi) - stoi(lo);
    }
};
